<script setup>
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import Icon from './GardenIcon.vue'
import Row from './NativeRow.vue'
import Detail from './NativeDetail.vue'
import Sheet from './GardenSheet.vue'
import Cover from './NativeCover.vue'
import WorkshopActivity from './WorkshopActivity.vue'
import { createWorkshopMetadataRuntime } from './workshopMetadataRuntime.js'
import { updateEligible } from './workshopRuntime.js'
import { selectIds, toggleAll } from './listSelection.js'
import { useBoxSelection } from './useBoxSelection.js'
import { createNativeWorkspaceRuntime } from './nativeWorkspaceRuntime.js'
import { nameOf, sizeText, dateText, changes, sourceText, missingDependencies, runLabel, equalOrder, stableSort } from './nativeModel.js'

const props = defineProps({ bridge: Object, installation: Object, active: Boolean, steam:Object, steamState:Object })
const emit = defineEmits(['state', 'busy', 'launch', 'logs', 'workshop', 'snapshot', 'profiles'])
const state = reactive({}), runtime = createNativeWorkspaceRuntime(props.bridge, state)
const media=reactive({}),metadata=createWorkshopMetadataRuntime(props.bridge,media)
const imageUrl=ref(''),steamAction=ref(null)
const focus = ref(null), tab = ref('overview'), drawer = ref(false), detail = ref(null), config = ref(null)
const selection = reactive({ list:'en', ids:[], anchor:null })
const marquee=useBoxSelection({getSelection:()=>selection,setSelection:value=>Object.assign(selection,value),canStart:()=>!blocked.value&&!dialog.value})
const selectionBox=marquee.rectangle
const availableQuery = ref(''), enabledQuery = ref(''), chip = ref('all'), sort = ref('name')
const availList = ref(null), enList = ref(null), availSearch = ref(null), enSearch = ref(null), basket = ref(null)
const dropMarker = ref(null)
const dialog = ref(null), operation = ref(false), dialogError = ref(''), menu = ref(null)
const pendingDisable = ref({ ids:[], affected:[] }), saveRun = ref(false), saveResult = ref(null)
const importPreview = ref(null), importName = ref(''), recoveries = ref([]), selectedRecovery = ref(null)
const ruleBefore = ref(''), ruleAfter = ref(''), currentAction = ref(null), rulesRevision = ref(null), editedRules = ref([])
let detailEpoch = 0, configEpoch = 0, launchResolver = null, drag = null, processTimer = null, disposed = false
const detailCache=new Map(),detailPending=new Map()
async function cachedDetail(installation_id,id){const key=`${installation_id}:${snapshot.value?.revision}:${id}`;if(detailCache.has(key))return detailCache.get(key);if(!detailPending.has(key))detailPending.set(key,props.bridge.request('native.detail',{installation_id,id}).then(value=>{detailCache.set(key,value.mod);if(detailCache.size>24)detailCache.delete(detailCache.keys().next().value);return value.mod}).finally(()=>detailPending.delete(key)));return detailPending.get(key)}
const snapshot = computed(() => state.snapshot)
const mods = computed(() => snapshot.value?.mods || [])
const byId = id => mods.value.find(m => m.id === id)
const selectedMod = computed(() => detail.value?.id === focus.value ? detail.value : byId(focus.value))
const missing = computed(() => missingDependencies(mods.value))
const selectedMissing = computed(() => missing.value.find(m => m.id === focus.value))
const delta = computed(() => changes(state.order, state.baseline))
const issues = computed(() => runtime.issues())
const blockers = computed(() => issues.value.filter(x => x.level === 'block'))
const writeAllowed = computed(() => runtime.canWrite() && !operation.value && !props.steam?.busy())
const enabledSet = computed(() => new Set(state.order))
const pool = computed(() => mods.value.filter(m => !enabledSet.value.has(m.id)))
const needsCare = m => Boolean(m.issues?.length || m.sources?.length > 1 || m.prerequisites?.some(id => !byId(id)))
const counts = computed(() => ({ all:pool.value.length, workshop:pool.value.filter(m=>m.source==='workshop').length, local:pool.value.filter(m=>m.source!=='workshop').length, care:pool.value.filter(needsCare).length }))
const available = computed(() => pool.value.filter(m => (!availableQuery.value || `${m.name} ${m.author} ${m.id} ${m.workshop_id}`.toLocaleLowerCase().includes(availableQuery.value.toLocaleLowerCase())) && (chip.value === 'all' || chip.value === 'care' && needsCare(m) || chip.value === 'workshop' && m.source === 'workshop' || chip.value === 'local' && m.source !== 'workshop')).sort((a,b) => sort.value === 'size' ? (b.size_bytes || 0)-(a.size_bytes || 0) : sort.value === 'updated' ? String(b.updated_at).localeCompare(String(a.updated_at)) : nameOf(a).localeCompare(nameOf(b),'zh-CN')))
const visibleEnabled = computed(() => state.order.map(id => byId(id) || { id,name:id,installed:false,capabilities:[],issues:[] }).filter(m => !enabledQuery.value || `${m.name} ${m.author} ${m.id}`.toLowerCase().includes(enabledQuery.value.toLowerCase())))
const approvalRequired = computed(() => state.order.filter(id => byId(id)?.approval?.state !== 'approved'))
const restartRequired = computed(() => state.order.filter(id => runLabel(byId(id), true, state.baseline.includes(id)).key === 'restart'))
const blocked = computed(() => state.busy || operation.value)
const sorted = computed(() => runtime.sorted())
const editedSort = computed(() => stableSort(state.order, mods.value, editedRules.value))
const rowIssue = id => issues.value.find(x => x.id === id)
const payload = () => ({ installation_id: props.installation.installation_id })
const steamItems=computed(()=>props.steam?.items()||{})
const updatable=computed(()=>mods.value.filter(m=>m.source==='workshop'&&updateEligible(steamItems.value[m.workshop_id])))
const selectedUpdates=computed(()=>updatable.value.filter(m=>selection.ids.includes(m.id)))
const updateSummary=computed(()=>{if(!props.steamState?.status)return props.steamState?.loading?'正在核对工坊状态…':'更新状态未知';const unknown=mods.value.filter(m=>m.source==='workshop'&&steamItems.value[m.workshop_id]?.needs_update==null).length;return `${updatable.value.length} 个模组待更新${unknown?` · ${unknown} 项待核对`:''}${props.steamState.stale&&props.steamState.hasObserved?'（上次记录）':''}`})
watch(()=>[props.installation?.installation_id,mods.value.map(m=>m.workshop_id).filter(Boolean).join(',')],([id,ids])=>{if(id)void metadata.load(id,ids?ids.split(','):[])},{immediate:true})
function confirmUpdate(all=false){steamAction.value={action:'update',mods:all?updatable.value:selectedUpdates.value};open('steam')}
async function performSteam(){if(!steamAction.value)return;const r=await props.steam.act(steamAction.value.action,steamAction.value.mods.map(m=>m.workshop_id));if(r)dialog.value=null}

watch(() => props.installation?.installation_id, async id => { close(); focus.value = null; detail.value = null; config.value = null; selection.ids=[]; await runtime.setInstallation(id); if(mods.value.length) await reveal(state.order[0] || mods.value[0].id) }, { immediate:true })
watch(snapshot, value => emit('snapshot', value))
watch([delta, blocked, () => state.loading, () => state.snapshot?.runtime?.state], () => { emit('state', { dirty:delta.value.dirty, loaded:Boolean(snapshot.value), locked:blocked.value || state.loading || snapshot.value?.runtime?.state !== 'stopped', changes:delta.value.count, running:snapshot.value?.runtime?.state === 'running' }); emit('busy',blocked.value) }, { immediate:true })
watch(tab, value => { if(value==='config') void loadConfig() })
watch(focus, async id => {
  config.value = null
  const token = ++detailEpoch, installationId = props.installation?.installation_id
  detail.value=detailCache.get(`${installationId}:${snapshot.value?.revision}:${id}`)||null
  if(!id || !byId(id) || !installationId) return
  try { const result = await cachedDetail(installationId,id); if(token === detailEpoch && !disposed) detail.value = result }
  catch(error){ if(token === detailEpoch) state.error=error.message }
  if(tab.value==='config') void loadConfig()
})
async function loadConfig() { const id=focus.value, token=++configEpoch; if(!id || !byId(id)) return; config.value=null; try { const value=await props.bridge.request('native.config.read',{...payload(),id}); if(token===configEpoch && id===focus.value)config.value=value } catch(error){if(token===configEpoch)config.value={error:error.message}} }
function select(mod,list,event={}) {
  const ids=(list==='en'?visibleEnabled.value:available.value).map(m=>m.id)
  Object.assign(selection,selectIds(selection,list,mod.id,ids,event));focus.value=mod.id;drawer.value=true
  nextTick(()=> (list==='en'?enList.value:availList.value)?.focus({preventScroll:true}))
}
function activateList(list){if(selection.list!==list)Object.assign(selection,{list,ids:[],anchor:null})}
function allSelected(list){const ids=(list==='en'?visibleEnabled.value:available.value).map(m=>m.id);return selection.list===list&&ids.length>0&&ids.every(id=>selection.ids.includes(id))}
function selectAll(list,force=false){Object.assign(selection,toggleAll(selection,list,(list==='en'?visibleEnabled.value:available.value).map(m=>m.id),force));nextTick(()=>(list==='en'?enList.value:availList.value)?.focus({preventScroll:true}))}
function pick(mod,list,event) { select(mod,list,{...event,ctrlKey:true}) }
async function reveal(id, targetTab) { if(!byId(id) && !missing.value.some(m=>m.id===id)) return; focus.value=id; if(targetTab)tab.value=targetTab; drawer.value=true; selection.list=state.order.includes(id)?'en':'avail';selection.ids=[id];selection.anchor=id;await nextTick();(selection.list==='en'?enList.value:availList.value)?.querySelector(`[data-id="${CSS.escape(id)}"]`)?.scrollIntoView({block:'nearest'}) }
function group(id,list){return selection.list===list && selection.ids.includes(id)?[...selection.ids]:[id]}
function toggle(id,event) { const list=state.order.includes(id)?'en':'avail',ids=group(id,list); if(list==='en')disable(ids,event);else enable(ids,undefined,event) }
function enable(ids, at, event) { if(blocked.value)return; const result=runtime.enable(ids,at); if(result.add.length){selection.list='en';selection.ids=ids.filter(id=>state.order.includes(id));selection.anchor=selection.ids[0];focus.value=selection.ids[0];fly(event?.currentTarget)} }
function disable(ids,event,force=false) { if(blocked.value)return; const result=runtime.disable(ids,force);if(result.confirmation){pendingDisable.value={ids,affected:result.affected};open('reverse');return}selection.list='avail';selection.ids=ids;selection.anchor=ids[0];focus.value=ids[0];fly(event?.currentTarget) }
function move(mode,id) { if(enabledQuery.value){state.notice='筛选中不能调整顺序，请先清除筛选。';return}if(id && !selection.ids.includes(id)){selection.ids=[id];selection.list='en'}runtime.move(selection.ids,mode) }
function fly(from){const to=basket.value?.querySelector('.basket-icon');if(!from||!to||matchMedia('(prefers-reduced-motion: reduce)').matches)return; const a=from.getBoundingClientRect(),b=to.getBoundingClientRect(),leaf=document.createElement('div');leaf.className='garden-flyleaf';leaf.innerHTML='<svg viewBox="0 0 24 24" fill="currentColor"><path d="M5 19C5 10 11 5 20 4c0 9-5 15-14 15z"/></svg>';document.body.appendChild(leaf);leaf.style.left=a.left+'px';leaf.style.top=a.top+'px';const dx=b.left-a.left,dy=b.top-a.top;leaf.animate([{transform:'translate(0,0)'},{transform:`translate(${dx*.5}px,${dy*.5-60}px) rotate(160deg)`},{transform:`translate(${dx}px,${dy}px) rotate(320deg) scale(.6)`,opacity:.3}],{duration:700,easing:'cubic-bezier(.22,1,.36,1)'}).onfinish=()=>{leaf.remove();basket.value?.classList.remove('bounce');requestAnimationFrame(()=>basket.value?.classList.add('bounce'))} }
function open(type){menu.value=null;dialogError.value='';dialog.value=type}
function close(){if(operation.value||state.busy)return;dialog.value=null;dialogError.value='';if(launchResolver){launchResolver(false);launchResolver=null}}
function confirmSave(run=false){saveRun.value=run;saveResult.value=null;open('save')}
function prepareLaunch(){if(!snapshot.value || snapshot.value.runtime?.state!=='stopped')return Promise.resolve(false);if(!delta.value.dirty && !approvalRequired.value.length)return Promise.resolve(true);confirmSave(true);return new Promise(resolve=>{launchResolver=resolve})}
async function save(){confirmSave(false);return false}
async function doSave(run){const wrote=delta.value.dirty;const result=await runtime.save();if(!result){dialogError.value=state.error;return}saveResult.value={...result,wrote};if(launchResolver){launchResolver(Boolean(run));launchResolver=null} }
async function refresh(){detailCache.clear();await runtime.refresh();if(focus.value && !delta.value.dirty){detail.value=null;const id=focus.value;if(byId(id))try{detail.value=(await props.bridge.request('native.detail',{...payload(),id})).mod}catch(error){state.error=error.message}}}
async function refreshInventory(){detailCache.clear();await runtime.refreshInventory();const id=focus.value,token=++detailEpoch;if(id&&byId(id))try{const result=await props.bridge.request('native.detail',{...payload(),id});if(token===detailEpoch&&id===focus.value)detail.value=result.mod}catch(error){state.error=error.message}}
async function operationCall(fn){if(operation.value)return;operation.value=true;dialogError.value='';try{return await fn()}catch(error){dialogError.value=error.message;state.error=error.message;return null}finally{operation.value=false}}
async function chooseImport(kind){await operationCall(async()=>{const chosen=await props.bridge.request('native.import.choose',{...payload(),kind});if(chosen.cancelled||!chosen.source_handle)return;await previewSource(chosen)})}
async function previewSource(source){importName.value=source.display_name || '';importPreview.value=await props.bridge.request('native.import.preview',{...payload(),source_handle:source.source_handle})}
async function commitImport(){if(!importPreview.value||!writeAllowed.value)return;const result=await operationCall(()=>props.bridge.request('native.import.commit',{...payload(),preview_id:importPreview.value.preview_id,expected_revision:importPreview.value.revision}));if(result){runtime.adopt(result);dialog.value=null;state.notice='完整模组包已导入，尚未启用。';await reveal(importPreview.value.package.id)}}
async function saveConfig(entries){if(!config.value||!writeAllowed.value)return;const result=await operationCall(()=>props.bridge.request('native.config.save',{...payload(),id:focus.value,expected_revision:config.value.revision,entries}));if(result){config.value=result;await refresh();state.notice='配置已保存并创建恢复点，游戏下次启动时读取。'}}
async function recovery(){open('recovery');await operationCall(async()=>{recoveries.value=(await props.bridge.request('native.recovery.list',payload())).items;selectedRecovery.value=null})}
async function restore(){const result=await operationCall(async()=>{const restored=await props.bridge.request('native.recovery.restore',{...payload(),id:selectedRecovery.value.id,expected_revision:snapshot.value.revision});return Array.isArray(restored.mods)?restored:props.bridge.request('native.snapshot',payload())});if(result){runtime.adopt(result);dialog.value=null;await refresh();if(tab.value==='config')await loadConfig();state.notice='恢复完成；游戏批准不会从历史恢复点复制。'}}
async function action(event){menu.value=null;const id=focus.value;if(event.kind==='copy'){try{await navigator.clipboard.writeText(event.value);state.notice='已复制 '+event.value}catch{state.error='剪贴板不可用，请选择文字手动复制。'}return}
  if(event.kind==='image'){imageUrl.value=event.url;open('image');return}
  if(event.kind==='unsubscribe'){steamAction.value={action:'unsubscribe',mods:[selectedMod.value]};open('steam');return}
  if(event.kind==='more'){menu.value={x:Math.min(event.event.clientX,window.innerWidth-260),y:Math.min(event.event.clientY,window.innerHeight-380)};return}
  if(event.kind==='logs'){emit('logs');return}if(event.kind==='search'){emit('workshop',event.value);return}if(event.kind==='recovery'){await recovery();return}if(event.kind==='rules'){ruleBefore.value=id||'';ruleAfter.value='';editedRules.value=state.rules.map(r=>({...r}));open('rules');await operationCall(async()=>{const result=await props.bridge.request('native.rules.read',payload());rulesRevision.value=result.revision;editedRules.value=result.rules.map(r=>({...r}))});return}
  if(['remove','switch-source'].includes(event.kind)){currentAction.value=event.kind;open('local');return}
  await operationCall(async()=>{if(event.kind==='open'){const r=await props.bridge.request('native.open',{...payload(),id,kind:event.target});if(!r.opened)state.notice=r.message}
    if(event.kind==='workshop'){const r=await props.bridge.request('workshop.open',{workshop_id:selectedMod.value.workshop_id,intent:'detail',target:'steam'});state.notice=r.message||'已打开 Steam 工坊页面。'}
    if(event.kind==='snapshot'){const r=await props.bridge.request('native.recovery.create',{...payload(),id});state.notice=`已创建恢复点 ${r.recovery_id || r.id || ''}`}
  })
}
async function localChange(){const result=await operationCall(()=>props.bridge.request(currentAction.value==='remove'?'native.local.remove':'native.source.switch',{...payload(),id:focus.value,expected_revision:snapshot.value.revision}));if(result){runtime.adopt(result);dialog.value=null;detail.value=null;await refresh()}}
async function saveRules(){
  if(!rulesRevision.value||editedSort.value.cycle.length)return
  const draft=[...state.order], oldBase=[...state.baseline]
  const result=await operationCall(()=>props.bridge.request('native.rules.save',{...payload(),expected_revision:rulesRevision.value,rules:editedRules.value}))
  if(!result)return
  rulesRevision.value=result.revision
  const latest=await operationCall(()=>props.bridge.request('native.snapshot',payload()))
  if(!latest)return
  runtime.adopt(latest);runtime.change(draft,'排序规则已保存，保留模组草稿')
  if(!equalOrder(oldBase,latest.enabled_ids)){state.externalChanged=true;state.notice='排序规则已保存，但游戏状态发生变化；请核对并重新读取。'}
  else state.notice='排序规则已保存并创建恢复点，草稿尚未写入游戏。'
  open('sort')
}
function beginDrag(mod,list,event){if(blocked.value)return event.preventDefault();drag={ids:group(mod.id,list),from:list};event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',drag.ids.join(','));event.currentTarget.classList.add('dragging')}
function dropIndex(event){const rows=[...enList.value.querySelectorAll('.row[data-id]')];for(const row of rows){const r=row.getBoundingClientRect();if(event.clientY<r.top+r.height/2)return state.order.indexOf(row.dataset.id)}return state.order.length}
function dragOver(list,event){if(!drag)return;if(list==='en'&&enabledQuery.value){event.dataTransfer.dropEffect='none';return}event.preventDefault();event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('drop-target');if(list==='en'){const rows=[...event.currentTarget.querySelectorAll('.row[data-id]')],at=dropIndex(event),row=rows.find(r=>state.order.indexOf(r.dataset.id)===at),box=event.currentTarget.getBoundingClientRect();dropMarker.value=(row?row.getBoundingClientRect().top:(rows.at(-1)?.getBoundingClientRect().bottom||box.top+10))-box.top+event.currentTarget.scrollTop-3}}
function drop(list,event){dropMarker.value=null;event.currentTarget.classList.remove('drop-target');if(!drag)return;event.preventDefault();const d=drag;drag=null;if(list==='en'){if(enabledQuery.value)return;const at=dropIndex(event);if(d.from==='en')runtime.drop(d.ids,at);else enable(d.ids,at)}else if(d.from==='en')disable(d.ids)}
function dragEnd(){drag=null;dropMarker.value=null;document.querySelectorAll('.formal-ui .dragging,.formal-ui .drop-target').forEach(el=>el.classList.remove('dragging','drop-target'))}
function keyboard(e){if(!props.active || blocked.value)return;if(dialog.value){if(e.key==='Escape')close();return}const input=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName),ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(ctrl&&key==='s'){e.preventDefault();if(delta.value.dirty&&writeAllowed.value)confirmSave();return}if(ctrl&&key==='f'){e.preventDefault();(selection.list==='en'?enSearch.value:availSearch.value)?.focus();return}if(input)return;if(ctrl&&key==='a'){e.preventDefault();selectAll(document.activeElement===availList.value?'avail':document.activeElement===enList.value?'en':selection.list,true);return}if(ctrl&&(key==='z'||key==='y')){e.preventDefault();key==='y'||e.shiftKey?runtime.redo():runtime.undo();return}if(e.altKey&&['ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();move({ArrowUp:'up',ArrowDown:'down',Home:'top',End:'bottom'}[e.key]);return}if(['ArrowUp','ArrowDown'].includes(e.key)){const list=selection.list==='en'?visibleEnabled.value:available.value;const index=list.findIndex(m=>m.id===focus.value);const m=list[Math.max(0,Math.min(list.length-1,index+(e.key==='ArrowUp'?-1:1)))];if(m){e.preventDefault();select(m,selection.list,e);nextTick(()=>document.querySelector(`.formal-ui .row[data-id="${CSS.escape(m.id)}"]`)?.scrollIntoView({block:'nearest'}))}return}if(['Enter','ArrowRight'].includes(e.key)&&selection.list==='avail'){e.preventDefault();enable(selection.ids)}else if(['Delete','ArrowLeft'].includes(e.key)&&selection.list==='en'){e.preventDefault();disable(selection.ids)}else if(e.key===' '&&focus.value){e.preventDefault();toggle(focus.value,e)} }
function jump(kind){const id=kind==='pending'?approvalRequired.value[0]:kind==='restart'?restartRequired.value[0]:issues.value.find(i=>i.level===kind)?.id;if(id)void reveal(id,kind==='pending'?'perm':kind==='restart'?'log':'deps')}
function fix(issue){if(issue.action==='enable')enable([issue.dep],state.order.indexOf(issue.id));if(issue.action==='sort')open('sort');if(issue.action==='workshop')emit('workshop',issue.dep)}
function importOpen(){importPreview.value=null;importName.value='';open('import')}
async function nativeDrop(e){if(!props.active||!props.installation||blocked.value)return;const sources=e.detail?.sources;if(!Array.isArray(sources)||!sources.length)return;importOpen();if(sources.length>1){dialogError.value='一次导入一个完整模组包，请分别选择。';return}await operationCall(()=>previewSource(sources[0]))}
async function applyProfile(order){if(!await runtime.refresh(true))return;runtime.change(order,'已载入方案');state.notice='方案已载入草稿；排序规则保存在管理器，模组列表仍需保存后才会写入游戏。'}
async function pollProcess(){if(disposed)return;try{if(props.installation&&!blocked.value){const r=await props.bridge.request('game.status',payload());const previous=snapshot.value?.runtime?.state;const s=r.state==='running'?'running':['stopped','not_started','exited','launchable'].includes(r.state)?'stopped':r.state==='unknown'?'unknown':null;if(s&&snapshot.value){snapshot.value.runtime={...snapshot.value.runtime,state:s};if(previous==='running'&&s==='stopped')await refresh()}}}catch{}finally{if(!disposed)processTimer=setTimeout(pollProcess,5000)}}
onMounted(()=>{window.addEventListener('keydown',keyboard);window.addEventListener('psmm-native-import',nativeDrop);window.addEventListener('dragend',dragEnd);void pollProcess()})
onUnmounted(()=>{disposed=true;++detailEpoch;++configEpoch;clearTimeout(processTimer);window.removeEventListener('keydown',keyboard);window.removeEventListener('psmm-native-import',nativeDrop);window.removeEventListener('dragend',dragEnd);runtime.dispose();metadata.dispose();if(launchResolver)launchResolver(false)})
defineExpose({refresh,refreshInventory,reveal,save,prepareLaunch,importOpen,recovery,applyProfile})
</script>

<template>
  <div class="formal-ui"><section class="page on" data-testid="native-workspace" :aria-busy="blocked || state.loading">
    <div class="garden-intro"><div><h1>模组</h1><p><b>{{ state.order.length }}</b> 个已启用 · {{ pool.length }} 个可用 · 改动后点“保存”才会写入游戏</p></div><div class="garden-intro-actions"><button class="garden-btn soft sm" @click="emit('workshop')"><Icon name="store" size="sm"/>创意工坊</button><button class="garden-btn soft icon sm" title="重新扫描" :disabled="blocked || state.loading" @click="refresh"><Icon name="refresh" size="sm"/></button><button class="garden-btn green" :disabled="!installation || blocked" @click="importOpen"><Icon name="plus" size="sm"/>导入</button></div></div>
    <div v-if="snapshot?.runtime?.state === 'running'" class="garden-sign-banner"><Icon name="lock"/><span class="grow"><b>游戏正在运行</b> · 可以先改好草稿，退出游戏后再保存，免得游戏用内存里的旧状态覆盖。</span></div>
    <div v-else-if="snapshot && !mods.length" class="garden-sign-banner"><Icon name="sprout"/><span class="grow">已识别 <b>Probably Stolen</b>。去创意工坊订阅模组，或导入本地模组包，就可以开始了。</span><button class="garden-btn green sm" @click="emit('workshop')">打开创意工坊</button></div>
    <div v-if="state.externalChanged" class="care-note">游戏状态或文件已有变化，草稿已保留。<button class="garden-link" @click="open('reload')">重新读取</button></div>
    <div v-if="state.error" class="garden-notice care" role="alert">{{ state.error }}<button class="garden-link" @click="state.error=''">关闭</button></div><div v-else-if="state.notice" class="garden-notice" role="status">{{ state.notice }}<button v-if="state.past.length" class="garden-link" @click="runtime.undo">撤销</button></div>
    <div v-if="installation" class="workshop-update-bar"><span><Icon name="steam" size="sm"/>{{ updateSummary }}</span><span v-if="!steam?.available('update')" class="muted">{{ steam?.reason('update') }}</span><span class="sp"></span><button class="garden-btn soft sm" :disabled="steamState?.loading" @click="steam?.refresh(true)">检查更新</button><button data-testid="mods-update-selected" class="garden-btn sm" :disabled="!selectedUpdates.length||!steam?.available('update')" @click="confirmUpdate(false)">更新选中 {{ selectedUpdates.length||'' }}</button><button data-testid="mods-update-all" class="garden-btn green sm" :disabled="!updatable.length||!steam?.available('update')" @click="confirmUpdate(true)">全部更新</button></div><WorkshopActivity :state="steamState" :mods="mods"/><div v-if="!installation" class="garden-empty"><span class="garden-pot"><Icon name="sprout"/></span><b>先选择游戏安装</b><span>点击右上角的游戏安装牌子，开始整理你的模组。</span></div>
    <div v-else class="beds" :class="{ multi:selection.ids.length>1 }">
      <section class="bed avail"><div class="bed-head"><h2><Icon name="pause-circle" size="sm"/>可用模组</h2><span class="sp"></span><button class="garden-link select-all" data-testid="mods-available-all" :disabled="!available.length" @click="selectAll('avail')">{{ allSelected('avail')?'取消全选':'全选' }}</button><span class="bed-count">{{ pool.length }}</span></div><div class="bed-tools"><label class="garden-search" :class="{has:availableQuery}"><Icon name="search" size="sm"/><input ref="availSearch" v-model="availableQuery" placeholder="搜索名称、作者或 ID"/><button class="search-clear" aria-label="清除搜索" @click="availableQuery=''"><Icon name="x" size="xs"/></button></label><span class="garden-select"><select v-model="sort" title="只影响这一栏的浏览顺序"><option value="name">名称</option><option value="updated">更新时间</option><option value="size">大小</option></select></span></div><div class="garden-chips sm"><button v-for="[key,label] in [['all','全部'],['workshop','工坊'],['local','本地'],['care','需处理']]" :key="key" :class="{on:chip===key,care:key==='care'}" @click="chip=key">{{ label }}<span>{{ counts[key] }}</span></button></div>
        <div ref="availList" class="bed-list" @pointerdown="marquee.start('avail',$event)" @focus="activateList('avail')" tabindex="0" role="listbox" aria-label="可用模组" aria-multiselectable="true" @dragover="dragOver('avail',$event)" @dragleave="$event.currentTarget.classList.remove('drop-target')" @drop="drop('avail',$event)">
          <div v-if="selectionBox?.list==='avail'" class="selection-box" :style="selectionBox.style"></div><template v-for="care in [false,true]" :key="String(care)"><div v-if="available.some(m=>needsCare(m)===care)" class="garden-bed-label" :style="care?'color:var(--g-rose)':null">{{ care?'需处理':'已安装 · 未启用' }} <span>{{ available.filter(m=>needsCare(m)===care).length }}</span></div><Row v-for="mod in available.filter(m=>needsCare(m)===care)" :key="mod.id" :mod="mod" :baseline="state.baseline.includes(mod.id)" :selected="selection.list==='avail'&&selection.ids.includes(mod.id)" :focused="focus===mod.id" :issue="rowIssue(mod.id)" :download="mod.source==='workshop'?steamItems[mod.workshop_id]:null" @select="select(mod,'avail',$event)" @pick="pick(mod,'avail',$event)" @toggle="toggle(mod.id,$event)" @drag="beginDrag(mod,'avail',$event)"/></template>
          <template v-if="!availableQuery && ['all','care'].includes(chip)"><div v-for="item in missing" :key="item.id" class="row ghost" @click="reveal(item.id)"><span class="garden-pot">?</span><div class="meta"><span class="nm">{{ item.id }}</span><span class="sub">未安装 · {{ item.neededBy.map(id=>nameOf(byId(id))).join('、') }} 需要它</span></div><span class="tg bad">缺失</span></div></template>
          <div v-if="!available.length && !missing.length" class="garden-empty" style="margin-top:6px"><span class="garden-pot"><Icon name="sprout"/></span><b>{{ !mods.length?'还没有模组':pool.length?'没有找到匹配模组':'都已启用' }}</b><span>{{ !mods.length?'去创意工坊订阅，或导入完整目录 / ZIP。':'把模组拖回这里即可停用。' }}</span></div>
        </div><div class="bed-foot">{{ selection.list==='avail'&&selection.ids.length>1?`已选 ${selection.ids.length} 个 · 按 Enter 一起启用`:'把模组拖到右边即可启用' }}</div></section>
      <section class="bed enabled"><div class="bed-head"><h2><Icon name="check-circle" size="sm"/>启用与顺序</h2><span class="sp"></span><button class="garden-btn sm" :disabled="blocked" title="依赖在前；可撤销" @click="open('sort')"><Icon name="wand" size="sm"/>自动排序</button><button class="garden-link select-all" data-testid="mods-enabled-all" :disabled="!visibleEnabled.length" @click="selectAll('en')">{{ allSelected('en')?'取消全选':'全选' }}</button><span class="bed-count">{{ state.order.length }}</span></div><div class="bed-tools"><label class="garden-search" :class="{has:enabledQuery}"><Icon name="search" size="sm"/><input ref="enSearch" v-model="enabledQuery" placeholder="在启用列表中查找"/><kbd>Ctrl F</kbd><button class="search-clear" aria-label="清除筛选" @click="enabledQuery=''"><Icon name="x" size="xs"/></button></label><div class="garden-view-switch"><button v-for="[key,title] in [['top','置顶 Alt+Home'],['up','上移 Alt+↑'],['down','下移 Alt+↓'],['bottom','置底 Alt+End']]" :key="key" :title="title" :disabled="!!enabledQuery || blocked" @click="move(key)"><Icon :name="key" size="sm"/></button></div></div><div v-if="enabledQuery" class="bed-filter"><Icon name="info" size="sm"/>正在筛选：只影响显示，顺序不变，拖动排序暂停。<button class="garden-link" @click="enabledQuery=''">清除筛选</button></div>
        <div ref="enList" class="bed-list" @pointerdown="marquee.start('en',$event)" @focus="activateList('en')" tabindex="0" role="listbox" aria-label="启用与顺序" aria-multiselectable="true" @dragover="dragOver('en',$event)" @dragleave="$event.currentTarget.classList.remove('drop-target')" @drop="drop('en',$event)"><div v-if="selectionBox?.list==='en'" class="selection-box" :style="selectionBox.style"></div><div v-if="dropMarker != null" class="drop-line" :style="{display:'block',top:dropMarker+'px'}"></div><Row v-for="mod in visibleEnabled" :key="mod.id" :mod="mod" enabled :baseline="state.baseline.includes(mod.id)" :index="state.order.indexOf(mod.id)" :selected="selection.list==='en'&&selection.ids.includes(mod.id)" :focused="focus===mod.id" :issue="rowIssue(mod.id)" :download="mod.source==='workshop'?steamItems[mod.workshop_id]:null" @select="select(mod,'en',$event)" @pick="pick(mod,'en',$event)" @toggle="toggle(mod.id,$event)" @move="move($event,mod.id)" @drag="beginDrag(mod,'en',$event)"/><div v-if="!visibleEnabled.length" class="garden-empty" style="margin-top:6px"><span class="garden-pot"><Icon name="sprout"/></span><b>{{ state.order.length?'没有找到匹配模组':'还没有启用的模组' }}</b><span>从左边拖进来，或打开开关。需要的依赖会一起加入。</span></div></div><div class="bed-foot"><Icon name="info" size="xs"/><span>这是保存顺序，不保证模组初始化的先后。<button class="garden-link" @click="open('order')">为什么</button></span><span class="sp"></span></div></section>
      <section v-if="selectedMissing" class="bed detail" :class="{open:drawer}"><div class="d-scroll"><div class="d-hero"><div class="cover"><Icon name="alert" size="lg"/></div><div class="hero-tools"><button title="关闭" @click="focus=null;drawer=false"><Icon name="x"/></button></div></div><div class="d-tags"><span class="tg bad">缺失的依赖</span></div><div class="d-title">{{ selectedMissing.id }}</div><div class="care-note">{{ selectedMissing.neededBy.map(id=>nameOf(byId(id))).join('、') }} 需要这个模组。原生 ID 不直接对应工坊条目，请搜索后选择，下载后再核对包里的 ID。</div><div class="note-act"><button class="garden-btn green sm" @click="emit('workshop',selectedMissing.id)">在创意工坊搜索</button><button class="garden-btn sm" @click="importOpen">指定本地包</button></div></div></section>
      <Detail v-else :bridge="bridge" :mod="selectedMod" :remote-cover="media.items[selectedMod?.workshop_id]?.preview_url" :cover-loading="media.loading" :mods="mods" :order="state.order" :baseline="state.baseline" :issues="issues" :tab="tab" :drawer="drawer" :config="config" :busy="blocked" :write-allowed="writeAllowed" @tab="tab=$event" @toggle="toggle(focus,$event)" @close="focus=null;drawer=false" @expand="open('expand')" @action="action" @goto="reveal" @fix="fix" @save-config="saveConfig"/>
    </div>
    <div v-if="snapshot" ref="basket" class="basket-bar" :class="{dirty:delta.dirty}"><span class="basket-icon"><Icon :name="delta.dirty?'basket':'check'"/></span><div class="basket-head"><b>{{ delta.dirty?`待保存 ${delta.count} 项`:'与游戏中保存的一致' }}</b><small>{{ delta.dirty ? steam?.busy()?'Steam 操作进行中，启用草稿已保留':!writeAllowed?'游戏未确认停止或状态已变化，暂不能写入':blockers.length?'有阻断问题，暂时不能应用到游戏':'保存后才会改动游戏文件' : snapshot.recovery_id?`恢复点 ${snapshot.recovery_id}`:'运行结果以最近启动日志为准' }}</small></div><div v-if="delta.dirty" class="basket-list"><span v-for="id in delta.added" :key="id"><span class="v on">启用</span>{{ nameOf(byId(id)) }}</span><span v-for="id in delta.removed" :key="id"><span class="v off">停用</span>{{ byId(id)?.name || id }}</span><span v-if="delta.moved"><span class="v ord">顺序</span>{{ delta.moved }} 处调整</span></div><span v-else style="flex:1"></span><div class="basket-pills"><button v-if="blockers.length" class="bp-bad" @click="jump('block')"><Icon name="alert" size="xs"/>{{ blockers.length }} 个阻断</button><button v-if="approvalRequired.length" class="bp-pend" @click="jump('pending')"><Icon name="shield" size="xs"/>{{ approvalRequired.length }} 个待游戏批准</button><button v-if="restartRequired.length" class="bp-off" @click="jump('restart')">{{ restartRequired.length }} 个待重启</button></div><div v-if="delta.dirty" class="basket-actions"><button class="garden-btn soft sm icon" title="撤销 Ctrl+Z" :disabled="!state.past.length||blocked" @click="runtime.undo"><Icon name="undo" size="sm"/></button><button class="garden-btn soft sm icon" title="重做 Ctrl+Y" :disabled="!state.future.length||blocked" @click="runtime.redo"><Icon name="redo" size="sm"/></button><button class="garden-btn soft sm" :disabled="blocked" @click="runtime.change(state.baseline,'放弃更改')">放弃</button><button class="garden-btn sm" :disabled="!writeAllowed||!!blockers.length" @click="confirmSave()">保存 <kbd>Ctrl S</kbd></button><button class="garden-btn green sm" :disabled="!writeAllowed||!!blockers.length" @click="emit('launch')"><Icon name="play" size="sm"/>保存并启动</button></div></div>

    <div v-if="menu" class="menu on" :style="{left:menu.x+'px',top:menu.y+'px'}" @mouseleave="menu=null"><h4>{{ nameOf(selectedMod) }}</h4><button @click="action({kind:'copy',value:focus})"><Icon name="copy" size="sm"/>复制原生 ID</button><button @click="action({kind:'open',target:'data'})"><Icon name="folder" size="sm"/>打开数据目录</button><button :disabled="!writeAllowed" @click="action({kind:'snapshot'})"><Icon name="history" size="sm"/>为它创建配置和数据快照</button><button @click="action({kind:'logs'})"><Icon name="sprout" size="sm"/>让 AI 解释它的日志</button><hr/><button v-if="selectedMod?.workshop_id" class="danger" :disabled="!steam?.available('unsubscribe')||steamItems[selectedMod.workshop_id]?.subscription_state!=='subscribed'" @click="action({kind:'unsubscribe'})"><Icon name="steam" size="sm"/>取消订阅…</button><button v-if="selectedMod?.source==='local'" class="danger" :disabled="!writeAllowed" @click="action({kind:'remove'})"><Icon name="x" size="sm"/>移除本地包…</button></div>
    <Sheet v-if="dialog==='reverse'" title="其他模组依赖它" :subtitle="`停用 ${pendingDisable.ids.map(id=>nameOf(byId(id))).join('、')} 后，下面的模组会缺少依赖。`" @close="close"><div class="lst"><div v-for="id in pendingDisable.affected" :key="id" class="li"><span class="garden-pot">{{ nameOf(byId(id)).slice(0,2) }}</span><div class="ln"><b>{{ nameOf(byId(id)) }}</b><span>依赖 {{ byId(id).prerequisites.join('、') }}</span></div></div></div><div class="mint-note">停用只是移出启用列表，不删除文件，也不取消订阅。</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="close">取消</button><button class="garden-btn green sm" @click="disable(pendingDisable.ids,null,true);close()">一起停用这 {{ pendingDisable.ids.length+pendingDisable.affected.length }} 个</button></template></Sheet>
    <Sheet v-if="dialog==='sort'" :title="sorted.cycle.length?'存在循环依赖':'自动排序'" subtitle="依赖在前；没有约束的模组保持现在的先后。" @close="close"><div v-if="sorted.cycle.length" class="care-note">{{ sorted.cycle.join(' → ') }}</div><div v-else-if="equalOrder(sorted.order,state.order)" class="mint-note">现在的顺序已满足所有依赖和规则，不需要调整。</div><div v-else class="lst"><div v-for="id in sorted.order.filter((id,i)=>state.order[i]!==id)" :key="id" class="li"><div class="ln"><b>{{ nameOf(byId(id)) }}：第 {{ state.order.indexOf(id)+1 }} 位 → 第 {{ sorted.order.indexOf(id)+1 }} 位</b><span>按已声明依赖与本次排序规则排列</span></div></div></div><div class="mint-note">这里调整的是<b>保存顺序</b>，不能保证模组初始化的先后。</div><template #footer><span class="hint">应用后可以 Ctrl+Z 撤销</span><span class="sp"></span><button class="garden-btn sm" @click="close">取消</button><button class="garden-btn green sm" :disabled="!!sorted.cycle.length||equalOrder(sorted.order,state.order)" @click="runtime.change(sorted.order,'自动排序');close()">应用</button></template></Sheet>
    <Sheet v-if="dialog==='save'" :title="saveResult?'保存完成':saveRun?'保存并启动':'保存到游戏'" subtitle="写入前重新读取游戏状态并自动备份；只改启用和顺序，其他设置保持不变。" :busy="state.busy" @close="close"><template v-if="saveResult"><div class="result"><div class="trust"><div class="ok"><small>目标状态</small><b>{{ saveResult.wrote ? '已写入并读回一致' : '已保存状态无更改' }}</b><span v-if="saveResult.recovery_id">恢复点 {{ saveResult.recovery_id }}</span></div></div><div class="trust"><div class="wait"><small>运行确认</small><b>{{ saveRun?'等待新的启动日志':'尚未确认运行' }}</b><span>批准由游戏完成，启动后刷新核对。</span></div></div></div></template><template v-else><div v-if="blockers.length" class="care-note"><b>有 {{ blockers.length }} 个阻断问题</b><p v-for="(issue,i) in blockers" :key="i">{{ issue.message }}</p></div><div class="sec" style="border:0;padding:0"><h3>本次变更</h3><div v-for="id in delta.added" :key="id" class="chg"><span class="tg on">启用</span>{{ nameOf(byId(id)) }}</div><div v-for="id in delta.removed" :key="id" class="chg"><span class="tg off">停用</span>{{ byId(id)?.name||id }}</div><div v-if="delta.moved" class="chg"><span class="tg sky">顺序</span>{{ delta.moved }} 个模组的位置有变化</div><div v-if="!delta.dirty" class="chg">没有变更，直接启动游戏</div></div><div v-if="saveRun&&approvalRequired.length" class="sec"><h3>启动后由游戏检查批准 <small>在这里一次列出</small></h3><div class="lst"><div v-for="id in approvalRequired" :key="id" class="li"><div class="ln"><b>{{ nameOf(byId(id)) }}</b><span>{{ byId(id)?.capabilities?.join(' · ') || '没有声明额外权限，批准状态仍由游戏判断' }}</span></div><button class="garden-link" @click="close();reveal(id,'perm')">权限详情</button></div></div></div><div class="sec"><h3>恢复点</h3><p>写入前自动创建恢复点。不会制造批准记录，失败保留可恢复副本。</p></div></template><p v-if="dialogError" class="care-note" role="alert">{{ dialogError }}</p><template #footer><span class="hint">保存成功不等于模组已经运行</span><span class="sp"></span><button class="garden-btn sm" :disabled="state.busy" @click="close">{{ saveResult?'完成':'取消' }}</button><template v-if="!saveResult"><button v-if="saveRun&&delta.dirty" class="garden-btn sm" :disabled="state.busy||!writeAllowed||!!blockers.length" @click="doSave(false)">只保存</button><button class="garden-btn green sm" :disabled="state.busy||!writeAllowed||!!blockers.length" @click="doSave(saveRun)">{{ state.busy?'正在写入并核对…':saveRun?'保存并启动':'保存' }}</button></template></template></Sheet>
    <Sheet v-if="dialog==='import'" title="导入模组" subtitle="支持完整模组目录或 ZIP；保留清单、依赖库和资源，不运行任何 DLL。" :busy="operation" @close="close"><div class="dropzone"><Icon name="import" size="lg"/><div>把完整目录或 ZIP 拖到应用窗口，或选择</div><div class="note-act" style="justify-content:center"><button class="garden-btn sm" :disabled="operation" @click="chooseImport('directory')">选择目录</button><button class="garden-btn sm" :disabled="operation" @click="chooseImport('zip')">选择 ZIP</button></div></div><div v-if="importPreview" class="sec"><h3>识别结果 · {{ importName }}</h3><dl class="garden-facts"><dt>模组</dt><dd>{{ importPreview.package.name }} · v{{ importPreview.package.version }}</dd><dt>原生 ID</dt><dd>{{ importPreview.package.id }}</dd><dt>文件</dt><dd>{{ importPreview.package.file_count ?? importPreview.package.files?.length }} 个 · {{ sizeText(importPreview.package.size_bytes) }}</dd><dt>目标</dt><dd>Mods/{{ importPreview.package.id }} · 导入后不会自动启用</dd></dl><p v-for="(issue,i) in importPreview.issues" :key="i" class="care-note">{{ issue.message || issue.detail || issue.code }}</p></div><div class="sign-note">裸 DLL、缺少 manifest.xml 的包不会被拆开写入游戏目录。</div><p v-if="dialogError" class="care-note" role="alert">{{ dialogError }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="operation" @click="close">取消</button><button class="garden-btn green sm" :disabled="!importPreview||importPreview.blocking||!writeAllowed" @click="commitImport">{{ operation?'处理中…':'添加到游戏模组目录' }}</button></template></Sheet>
    <Sheet v-if="dialog==='recovery'" title="恢复点" subtitle="每次写入前创建；恢复只还原选中操作，不复制历史批准。" :busy="operation" @close="close"><div v-if="!recoveries.length" class="garden-empty">还没有恢复点。</div><div class="lst"><label v-for="point in recoveries" :key="point.id" class="li"><input v-model="selectedRecovery" type="radio" :value="point" :disabled="point.restorable === false"/><div class="ln"><b>{{ point.label || point.kind }}</b><span>{{ dateText(point.created_at) }} · {{ point.restorable === false ? '备份未完成 / 无游戏变更' : ({committed:'已完成',restored:'已恢复',prepared:'写入未确认',failed:'失败，可恢复'})[point.status] || point.status }}</span></div></label></div><div v-if="selectedRecovery" class="sign-note">恢复前也会创建新的恢复点。当前草稿将重新读取，游戏需要重新检查批准。</div><p v-if="dialogError" class="care-note">{{ dialogError }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="operation" @click="close">关闭</button><button class="garden-btn green sm" :disabled="!selectedRecovery||selectedRecovery.restorable === false||!writeAllowed||delta.dirty" @click="restore">恢复选中记录</button></template></Sheet>
    <Sheet v-if="dialog==='order'" title="为什么说“保存顺序”" subtitle="当前已分析正式版的加载过程" @close="close"><div class="logline">读取批准与 modOrder → 加载本地模组 → 加载工坊模组
→ 应用保存顺序 → 检查依赖 → 加载资源</div><div class="mint-note">DLL 加载时已经打补丁并完成初始化，顺序在这之后才应用。因此它会影响之后的资源加载，<b>不能保证初始化先后</b>。</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="close">知道了</button></template></Sheet>
    <Sheet v-if="dialog==='expand'&&selectedMod" :title="nameOf(selectedMod)" :subtitle="`${selectedMod.author||'未注明作者'} · v${selectedMod.version||'未知'} · ${sourceText(selectedMod)}`" wide @close="close"><Detail :bridge="bridge" expanded :mod="selectedMod" :remote-cover="media.items[selectedMod?.workshop_id]?.preview_url" :cover-loading="media.loading" :mods="mods" :order="state.order" :baseline="state.baseline" :issues="issues" :tab="tab" :config="config" :write-allowed="writeAllowed" @action="action" @goto="close();reveal($event)" @fix="fix"/></Sheet>
    <Sheet v-if="dialog==='rules'" title="排序规则" subtitle="A 在 B 之前；规则单独保存，不会改变游戏的 DLL 初始化机制。" @close="close"><div class="rule-editor"><select v-model="ruleBefore" aria-label="在前的模组"><option value="">选择模组 A</option><option v-for="m in mods" :key="m.id" :value="m.id">{{ nameOf(m) }}</option></select><span>在</span><select v-model="ruleAfter" aria-label="在后的模组"><option value="">选择模组 B</option><option v-for="m in mods" :key="m.id" :value="m.id">{{ nameOf(m) }}</option></select><span>之前</span><button class="garden-btn sm" :disabled="!ruleBefore||!ruleAfter||ruleBefore===ruleAfter" @click="editedRules.push({before:ruleBefore,after:ruleAfter})">添加</button></div><div class="lst"><div v-for="(rule,i) in editedRules" :key="i" class="li"><div class="ln">{{ nameOf(byId(rule.before)) }} → {{ nameOf(byId(rule.after)) }}</div><button class="garden-btn soft xs" @click="editedRules.splice(i,1)">移除</button></div></div><div v-if="editedSort.cycle.length" class="care-note">与依赖或其他规则形成环：{{ editedSort.cycle.join(' → ') }}</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="close">关闭</button><button class="garden-btn green sm" :disabled="!writeAllowed||!rulesRevision||!!editedSort.cycle.length" @click="saveRules">保存规则并预览排序</button></template></Sheet>
    <Sheet v-if="dialog==='reload'" title="重新读取游戏状态" subtitle="你的未保存草稿将被当前游戏状态替换。" @close="close"><div class="sign-note">确认前可关闭面板，继续查看和记录当前草稿。</div><template #footer><span class="sp"></span><button class="garden-btn sm" @click="close">保留草稿</button><button class="garden-btn green sm" @click="runtime.refresh(true);close()">重新读取</button></template></Sheet>
    <Sheet v-if="dialog==='local'" :title="currentAction==='remove'?'移除本地包':'改用工坊版'" :busy="operation" @close="close"><div class="sign-note">{{ currentAction==='remove'?'本地包会保存到恢复点后移出 Mods，不删除配置或存档。':'本地副本会移入恢复点，使 Steam 工坊副本成为有效来源。游戏将重新核对批准。' }}</div><p>{{ nameOf(selectedMod) }} · {{ focus }}</p><p v-if="delta.dirty" class="care-note">请先保存或放弃模组草稿。</p><p v-if="dialogError" class="care-note">{{ dialogError }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="operation" @click="close">取消</button><button class="garden-btn clay sm" :disabled="!writeAllowed||delta.dirty" @click="localChange">创建恢复点并继续</button></template></Sheet>
    <Sheet v-if="dialog==='image'" :title="nameOf(selectedMod)" subtitle="完整封面" wide @close="close"><div class="full-cover"><Cover :src="imageUrl" :title="nameOf(selectedMod)"/></div></Sheet>
    <Sheet v-if="dialog==='steam'" :title="steamAction?.action==='update'?'更新工坊模组':'取消订阅模组'" :busy="steamState?.pending" @close="close"><p class="sign-note">{{ steamAction?.action==='update'?'由 Steam 下载当前版本；不会修改你的启用草稿。更新后游戏会重新核对批准。':'取消订阅可能由 Steam 移除包文件；当前启用草稿、配置和存档不会被管理器清除。' }}</p><div v-for="m in steamAction?.mods" :key="m.id" class="li">{{ nameOf(m) }}</div><p v-if="steamState?.error" class="care-note">{{ steamState.error }}</p><template #footer><span class="sp"></span><button class="garden-btn sm" :disabled="steamState?.pending" @click="close">取消</button><button data-testid="mods-steam-confirm" class="garden-btn green sm" :disabled="!steam?.available(steamAction?.action)" @click="performSteam">{{ steamAction?.action==='update'?'开始更新':'确认取消订阅' }}</button></template></Sheet>
  </section></div>
</template>
